import { test, expect, type Page, type Route } from "@playwright/test";
const api = process.env.SF_API_URL ?? "http://localhost:5001/v1";

// When explanations are generated by a hosted provider, the words must say so: what is sent, who generated it, and what happened
// when the free quota ran out. A response that does not name the provider keeps the local wording. The hosted endpoints are faked
// here; the real server path is covered by the API e2e suite.
async function setup(page: Page, tag: string) {
  await page.goto("/register");
  await page.getByLabel("Name", { exact: true }).fill("AI Hosted");
  await page.getByLabel("Email", { exact: true }).fill("aih-" + Date.now() + "-" + tag + "@example.test");
  await page.getByLabel("Password", { exact: true }).fill("AI-Hosted-2026!");
  await page.locator("#reg-terms").check();
  await page.getByRole("button", { name: "Create account", exact: true }).click();
  await expect(page.getByRole("button", { name: "Account menu", exact: true })).toBeVisible();
}
async function openTemplate(page: Page) {
  await page.goto("/new/template");
  await page.getByRole("button", { name: "Use Single-server MVP", exact: true }).click();
  await expect(page.getByLabel("Component", { exact: true })).toBeVisible();
}
async function recordRun(page: Page) {
  const accepted = page.waitForResponse((r) => r.url().endsWith("/simulate") && [200, 202].includes(r.status()));
  await page.getByRole("button", { name: "Run test", exact: true }).click();
  const run = (await (await accepted).json()).data.run;
  await expect(page).toHaveURL(new RegExp("/results\\?run=" + run.id));
  await expect(page.getByRole("heading", { name: "Topology under load" })).toBeVisible({ timeout: 30_000 });
  return { designId: new URL(page.url()).pathname.split("/")[2], runId: run.id as string };
}
const noOverflow = async (page: Page) => expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1)).toBe(true);
const drawer = (page: Page) => page.getByRole("complementary", { name: "Result explanation" });

type Mode = { provider?: "groq" | "ollama"; reason: string; retryAfterSeconds?: number; outcome: "completed" | "failed"; failure?: string };
function fakeAi(page: Page, ids: { designId: string; runId: string }, mode: Mode) {
  const jobId = "55555555-5555-4555-8555-555555555555";
  let submitted = false;
  const hosted = mode.provider === "groq";
  const job = () => ({
    id: jobId, designId: ids.designId, requestId: "66666666-6666-4666-8666-666666666666", designRevision: 1, versionId: "77777777-7777-4777-8777-777777777777",
    runId: ids.runId, fingerprint: "a".repeat(64), model: hosted ? "openai/gpt-oss-20b" : "qwen2.5:1.5b", modelDigest: hosted ? "hosted-model-digest-unavailable" : "b".repeat(64),
    promptVersion: "m12-explain-v1", schemaVersion: "m12-explanation-v1", status: mode.outcome, createdAt: new Date(Date.now() - 4000).toISOString(), completedAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + 86400000).toISOString(),
    result: mode.outcome === "completed" ? { summary: "The recorded run misses its latency target.", evidenceIds: ["verdict", "p95"], claims: ["latency_above_target"] } : null,
    failure: mode.outcome === "failed" ? { reason: mode.failure ?? "PROVIDER_UNAVAILABLE", message: "x" } : null,
    experimental: true,
    ...(mode.provider ? { provider: mode.provider } : {}),
    ...(hosted ? { returnedModel: "openai/gpt-oss-20b", usage: { promptTokens: 400, completionTokens: 120, totalTokens: 520 }, latencyMs: 1234 } : {}),
  });
  const evidence = () => ({
    jobId, designId: ids.designId, runId: ids.runId, designRevision: 1, fingerprint: "a".repeat(64), engineVersion: "reference-port-v1", structured: true,
    facts: { verdict: "fail", p95Ms: 2068.67, p95TargetMs: 300, errorRateFraction: 0.99012, errorBudgetFraction: 0.01, bottleneck: { id: "app", label: "App servers", utilizationFraction: 0.99152 } },
    evidenceIds: ["verdict", "p95", "errorRate", "bottleneck"], statements: ["p95 latency 2,068.67 ms is above the 300 ms target."],
    limitations: ["Mathematical model estimates, not measured infrastructure performance."],
  });
  const ok = (route: Route, data: unknown, status = 200) => route.fulfill({ status, json: { data } });
  return {
    async install() {
      await page.route(api + "/ai/**", async (route) => {
        const req = route.request();
        const path = new URL(req.url()).pathname.replace(/^\/v1/, "");
        if (path === "/ai/readiness")
          return ok(route, { enabled: true, ready: mode.reason === "AVAILABLE", model: hosted ? "openai/gpt-oss-20b" : "qwen2.5:1.5b", reason: mode.reason, ...(mode.provider ? { provider: mode.provider } : {}), ...(mode.retryAfterSeconds ? { retryAfterSeconds: mode.retryAfterSeconds } : {}) });
        if (path === "/ai/jobs" && req.method() === "POST") {
          const replay = submitted;
          submitted = true;
          return ok(route, { job: job(), statusUrl: "/v1/ai/jobs/" + jobId }, replay ? 200 : 202);
        }
        if (path === "/ai/jobs/" + jobId + "/evidence") return ok(route, evidence());
        if (path === "/ai/jobs/" + jobId) return ok(route, job());
        return route.continue();
      });
    },
  };
}
async function open(page: Page, tag: string, mode: Mode) {
  await setup(page, tag);
  const ids = { designId: "", runId: "" };
  const ai = fakeAi(page, ids, mode);
  await ai.install();
  await openTemplate(page);
  Object.assign(ids, await recordRun(page));
  return ids;
}

test("hosted: the trigger, the notice and the tag say the facts go to Groq, and nothing claims it stays local", async ({ page }, info) => {
  await open(page, "notice-" + info.project.name, { provider: "groq", reason: "AVAILABLE", outcome: "completed" });
  await expect(page.getByText(/Hosted, experimental AI \(Groq\)\. It sends the facts of this result to Groq/)).toBeVisible();
  await expect(page.getByText(/Local, experimental AI/)).toHaveCount(0);
  await page.getByRole("button", { name: "Explain this result", exact: true }).first().click();
  const notice = drawer(page).getByTestId("hosted-notice");
  await expect(notice).toBeVisible();
  await expect(notice).toContainText("Sent to Groq (hosted): the verdict, the p95 and its target, the error rate and its budget, and the bottleneck's label and utilization for this saved run");
  await expect(notice).toContainText("Nothing else from your design or your account");
  await expect(notice).toContainText("30 days unless Zero Data Retention is turned on");
  await expect(drawer(page).locator('[title*="Nothing leaves this computer"]')).toHaveCount(0);
  await expect(drawer(page).locator('[title*="Hosted model (Groq)"]')).toBeVisible();
  await expect(drawer(page).getByText("Hosted experimental AI (Groq).")).toBeVisible();
  await expect(drawer(page).getByText("Local experimental AI.")).toHaveCount(0);
  await noOverflow(page);
});

test("hosted: a finished explanation is labelled as hosted and its provenance shows the provider, no digest, tokens and time", async ({ page }, info) => {
  await open(page, "done-" + info.project.name, { provider: "groq", reason: "AVAILABLE", outcome: "completed" });
  await page.getByRole("button", { name: "Explain this result", exact: true }).first().click();
  await drawer(page).getByRole("button", { name: "Explain this result", exact: true }).click();
  const ai = drawer(page).getByRole("region", { name: "AI interpretation" });
  await expect(ai.getByText("Experimental · generated by a hosted model")).toBeVisible();
  await expect(ai.getByText("Experimental · generated locally")).toHaveCount(0);
  await ai.getByText("Provenance", { exact: true }).click();
  await expect(ai).toContainText("openai/gpt-oss-20b · no digest (hosted model)");
  await expect(ai).toContainText("Generated by");
  await expect(ai).toContainText("Groq (hosted)");
  await expect(ai).toContainText("Model reported");
  await expect(ai).toContainText("400 in · 120 out · 520 total");
  await expect(ai).toContainText("1.2 s");
  await expect(drawer(page).getByText(/Generating locally/)).toHaveCount(0);
  await noOverflow(page);
});

test("hosted: when the free quota is used up the drawer says so with the wait, and does not offer a request that would be refused", async ({ page }, info) => {
  await open(page, "quota-" + info.project.name, { provider: "groq", reason: "QUOTA_EXHAUSTED", retryAfterSeconds: 300, outcome: "completed" });
  await page.getByRole("button", { name: "Explain this result", exact: true }).first().click();
  await expect(drawer(page)).toContainText("The free hosted quota is used up for now. You can try again in about 5 minutes.");
  await expect(drawer(page).getByRole("button", { name: "Explain this result", exact: true })).toBeDisabled();
  await expect(drawer(page).getByRole("button", { name: "Check again", exact: true })).toBeVisible();
  await expect(drawer(page).getByText(/local model|Start it|free memory/)).toHaveCount(0);
});

test("hosted: a job the provider rate limited fails with the quota explanation and nothing was retried", async ({ page }, info) => {
  await open(page, "limited-" + info.project.name, { provider: "groq", reason: "AVAILABLE", outcome: "failed", failure: "PROVIDER_RATE_LIMITED" });
  await page.getByRole("button", { name: "Explain this result", exact: true }).first().click();
  await drawer(page).getByRole("button", { name: "Explain this result", exact: true }).click();
  await expect(drawer(page)).toContainText("Groq's free quota was reached, so this explanation did not finish. Nothing was retried. Try again later.");
});

test("local: a provider that is not hosted, or not named, keeps the local wording", async ({ page }, info) => {
  await open(page, "local-" + info.project.name, { provider: "ollama", reason: "AVAILABLE", outcome: "completed" });
  await expect(page.getByText(/Local, experimental AI\. It explains saved revision/)).toBeVisible();
  await expect(page.getByText(/Hosted, experimental AI/)).toHaveCount(0);
  await page.getByRole("button", { name: "Explain this result", exact: true }).first().click();
  await expect(drawer(page).getByTestId("hosted-notice")).toHaveCount(0);
  await expect(drawer(page).locator('[title*="Nothing leaves this computer"]')).toBeVisible();
  await drawer(page).getByRole("button", { name: "Explain this result", exact: true }).click();
  await expect(drawer(page).getByText("Experimental · generated locally")).toBeVisible();
});
